import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_SALT = os.environ.get('HMAC_SALT', 'changeme')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DATABASE)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        email TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        action TEXT,
        target_user TEXT,
        performed_by TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department or role for directory listing."""
    field = request.args.get('field', 'department')
    value = request.args.get('value', '')
    # Restrict searchable fields to prevent arbitrary column access
    allowed_fields = ['department', 'role', 'username']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid search field'}), 400
    # Build query - field is validated against allowlist above
    query = f"SELECT username, email, department, role FROM users WHERE {field} = ?"
    db = get_db()
    results = db.execute(query, (value,)).fetchall()
    return jsonify([dict(r) for r in results])

@app.route('/api/users/lookup', methods=['GET'])
def lookup_user():
    """Lookup user details with flexible filtering."""
    filter_expr = request.args.get('filter', '')
    if not filter_expr:
        return jsonify({'error': 'filter parameter required'}), 400
    # Basic sanitization - remove dangerous keywords
    dangerous = ['DROP', 'DELETE', 'INSERT', 'UPDATE', 'ALTER', 'EXEC', '--', ';']
    check = filter_expr.upper()
    for kw in dangerous:
        if kw in check:
            return jsonify({'error': 'Invalid filter expression'}), 400
    # Additional check: must start with a known column name
    valid_starts = ('username', 'email', 'department', 'role')
    if not any(filter_expr.lower().startswith(v) for v in valid_starts):
        return jsonify({'error': 'Filter must reference a valid column'}), 400
    query = f"SELECT username, email, department, role FROM users WHERE {filter_expr}"
    db = get_db()
    try:
        results = db.execute(query).fetchall()
    except sqlite3.OperationalError as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 400
    return jsonify([dict(r) for r in results])

@app.route('/api/users/report', methods=['POST'])
def generate_report():
    """Generate filtered user report for HR."""
    data = request.get_json(force=True)
    conditions = data.get('conditions', [])
    if not conditions or not isinstance(conditions, list):
        return jsonify({'error': 'conditions array required'}), 400
    where_parts = []
    for cond in conditions:
        col = cond.get('column', '')
        op = cond.get('op', '=')
        val = cond.get('value', '')
        if col not in ('department', 'role', 'username', 'email'):
            continue
        if op not in ('=', '!=', 'LIKE'):
            continue
        where_parts.append(f"{col} {op} '{val}'")
    if not where_parts:
        return jsonify({'error': 'No valid conditions'}), 400
    query = "SELECT username, email, department, role FROM users WHERE " + " AND ".join(where_parts)
    db = get_db()
    try:
        results = db.execute(query).fetchall()
    except sqlite3.OperationalError:
        return jsonify({'error': 'Report generation failed'}), 500
    # Log report generation
    db.execute("INSERT INTO audit_log (action, performed_by) VALUES (?, ?)",
               ('report_generated', request.headers.get('X-User', 'anonymous')))
    db.commit()
    return jsonify({'count': len(results), 'data': [dict(r) for r in results]})

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
